const i={ui:{fig:"Рис. 6",title:"Потайная молния",svgLabel:"Изометрический рисунок: как вшить потайную молнию в шов. Шов оставлен открытым; молния раскрыта, спираль разглажена с изнанки чуть тёплым утюгом; молния лицом вниз на лицевой стороне одной детали, спираль — по линии шва, прострочена лапкой для потайной молнии сверху вниз, пока лапка не упрётся в бегунок; вторая сторона так же, спираль в другой канавке, верхние края вровень; молния закрыта; шов ниже прошит лапкой для молнии; концы ленты пришиты только к припускам. Снаружи видны только линия шва и бегунок.",prev:"Предыдущий шаг",dot:(t,e)=>t?`Шаг ${t}: ${e}`:e,start:"Шаги →",next:"Дальше →",overview:"Обзор",stepOf:(t,e)=>`Шаг ${t} из ${e}`,machine:t=>`Машина: ${t.toLowerCase()}`,inThisStep:"В этом шаге",takeApart:"Посмотреть сквозь ткань",putTogether:"Вернуть ткань",replay:"↻ Повторить",parts:"Детали",allSteps:"Пошаговая инструкция",endView:"ВИД С ТОРЦА"},stitches:{straight:"Прямая строчка"},labels:{seamOpen:"шов оставить открытым",zipperFirst:"сначала молния",openZip:"раскрыть молнию",fromBack:"разгладить спираль с изнанки",coolIron:"чуть тёплый утюг",faceDown:"молния лицом вниз",coilOnSeam:"спираль по линии шва",oneGroove:"спираль в канавке",topDown:"сверху вниз",toPull:"пока лапка не упрётся в бегунок",otherPiece:"другая деталь лицом вверх",freeHalf:"свободная половина лицом вниз",topsLevel:"верхние края вровень",notTwisted:"не перекрутить",otherGroove:"спираль в другой канавке",close:"закрыть молнию",rightSides:"лицом к лицу",aboveSide:"чуть выше, в стороне",zipperFoot:"лапка для молнии",tapeEnds:"только к припускам",rightUp:"лицом вверх",onlyPull:"только линия шва и бегунок"},steps:[{title:"Потайная молния",text:"Снаружи молнии не видно: только линия шва и бегунок. Нажмите, чтобы посмотреть сквозь ткань."},{title:"Шов оставьте открытым",text:"Шов пока не сшивайте: потайную молнию вшивают первой, а шов ниже неё — потом.",details:["Оставьте шов открытым: молнию вшивают в несшитые края.","Шов ниже молнии сшивают, когда молния уже вшита."]},{title:"Разгладьте спираль",text:"Раскройте молнию. С изнанки разгладьте спираль чуть тёплым утюгом.",details:["Возьмите потайную молнию чуть длиннее разреза.","Раскройте молнию до конца.","Переверните её изнанкой вверх и разгладьте спираль чуть тёплым утюгом: горячий утюг плавит спираль."]},{title:"Молния лицом вниз",text:"Положите раскрытую молнию лицом вниз на лицевую сторону одной детали, спиралью точно по линии шва, и приколите.",details:["Положите одну половину раскрытой молнии лицом вниз на лицевую сторону одной детали.","Спираль — точно по линии шва, лента — на припуске.","Приколите ленту булавками."]},{title:"Первая сторона",text:"Поставьте лапку для потайной молнии: спираль — в одной из её канавок. Прострочите сверху вниз, пока лапка не упрётся в бегунок, и сделайте закрепку.",details:["Поставьте лапку для потайной молнии: спираль идёт в одной из двух канавок под ней.","Прострочите сверху вниз, рядом со спиралью, пока лапка не упрётся в бегунок.","Сделайте там закрепку.","Держите спираль в канавке: если строчка захватит спираль, молния не закроется."]},{title:"Вторая сторона",text:"Положите другую деталь лицом вверх и переложите на неё первую лицом к лицу, отогнув её припуск с пришитой половиной молнии. Свободная половина молнии ложится лицом вниз на другую деталь, спиралью по линии шва.",details:["Положите другую деталь лицом вверх.","Переложите на неё первую деталь лицом к лицу, а её припуск с пришитой половиной молнии отогните.","Свободную половину молнии положите лицом вниз на лицевую сторону другой детали, спиралью точно по линии шва.","Совместите верхние края и поперечные швы, если они есть: молнию не перекрутите. Приколите."]},{title:"Прострочите вторую сторону",text:"Спираль — в другой канавке лапки для потайной молнии. Прострочите сверху вниз, пока лапка не упрётся в бегунок, и сделайте закрепку.",details:["Вставьте спираль в другую канавку лапки.","Прострочите сверху вниз, рядом со спиралью, пока лапка не упрётся в бегунок.","Сделайте там закрепку. Спираль в строчку не попадает."]},{title:"Закройте молнию",text:"Закройте молнию: бегунок доходит до самого верха.",details:["Закройте молнию до конца.","Она идёт легко, если спираль не попала в строчку."]},{title:"Шов ниже",text:"Сложите детали лицом к лицу и поставьте лапку для молнии. Прошейте шов ниже молнии, начиная чуть выше и в стороне от конца строчки молнии.",details:["Сложите детали лицом к лицу, срезы ровно.","Поставьте обычную лапку для молнии.","Начните чуть выше и в стороне от конца строчки молнии и прошейте шов до конца."]},{title:"Концы ленты",text:"Отогните припуски и пришейте концы ленты молнии только к припускам, не к самим деталям.",details:["Отогните припуски.","Пришейте каждый конец ленты молнии только к своему припуску, не к детали."]},{title:"Лицом вверх",text:"Разверните детали и переверните лицом вверх. Снаружи видны только линия шва и бегунок.",details:["Разверните детали и переверните лицом вверх.","Снаружи видны только линия шва и бегунок."]}],legend:[{title:"Ткань",text:"две детали, соединённые по линии шва · строчек не видно"},{title:"Линия шва",text:"в ней прячется спираль · ниже молнии — обычный шов"},{title:"Молния",text:"под тканью · лента пришита только к припускам"},{title:"Бегунок",text:"единственное, что видно от молнии"}]};export{i as default};
